const $=id=>document.getElementById(id),esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const paths={code:'m8 6-6 6 6 6m8-12 6 6-6 6M14 3l-4 18',plan:'M5 3h14v18H5Z M8 7h8 M8 12h8 M8 17h5',library:'M5 3h10l5 5v13H5Z M15 3v6h5 M8 13h8 M8 17h6',logo:'M5 8 12 4l7 4v8l-7 4-7-4Z M8 9l4-2 4 2-4 2Z',practice:'M12 3v8l5-3 M19 8a8 8 0 1 1-9-4 M8 12a4 4 0 1 0 7-3',test:'M3 6h18v12H3Z M6 9h1m3 0h1m3 0h1m3 0h1 M6 12h1m3 0h1m3 0h1m3 0h1 M7 15h10',lessons:'M12 6v15 M12 6Q7 3 3 5v14q5-2 9 2 M12 6q5-3 9-1v14q-5-2-9 2',stats:'M4 19V5 M4 19h17 M8 16v-5 M13 16V8 M18 16V4',records:'m3 7 4 4 5-7 5 7 4-4-2 11H5Z M5 21h14',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M10 3h4l1 3 3 1 3 2v4l-3 1-1 3-2 3h-4l-1-3-3-1-3-2v-4l3-1 1-3Z',help:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M9.5 9a2.5 2.5 0 1 1 4.5 1.5L12 13 M12 16h.01',theme:'M4 3h6v17H4Z M10 7h6v13h-6 M16 12h5v8h-5 M7 16h.01',globe:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M3 12h18 M12 3q8 9 0 18-8-9 0-18',user:'M12 4a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M5 21v-2a7 7 0 0 1 14 0v2',restart:'M4 10a8 8 0 1 1 1 8 M4 4v6h6',close:'m6 6 12 12 M6 18 18 6',arrow:'M4 12h16 M14 6l6 6-6 6',speed:'M4 18a9 9 0 1 1 16 0 M12 13l5-5 M5 18h14',target:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10 M12 10v4 M10 12h4',daily:'M12 3v8l6-3 M20 10a8 8 0 1 1-11-6',check:'m5 12 4 4 10-10',pause:'M8 5v14 M16 5v14',play:'m7 4 13 8-13 8Z',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.help}"/></svg>`;
function loadInitialData(){try{const raw=localStorage.getItem(STORAGE_KEY);if(raw&&JSON.parse(raw)?.version!==2)throw new Error('Unknown data format');return parseBackup(backupData(ensureLearning(loadData(localStorage))))}catch{const fallback=ensureLearning(loadData({getItem:()=>null}));fallback.recoveryNeeded=true;return fallback;}}
let data=loadInitialData(),settings=data.settings,view='practice',session=null,context=null,finishedHandled=false,focused=false,wordView=null,forcedFocus=null,toastTimer=null,settingsTab='practice',settingsInDialog=false,resetAfterSettings=false,guideStep=0;
ensureLearning(data);
settings.wordsView='rows';
const progressStore=new ProgressStore({storage:localStorage,getData:()=>data,onData:value=>{data=value;settings=data.settings;settings.wordsView='rows';}});
let activityPayload=null,hintUntil=0,codeTrack='javascript',codeRound=-1;
let p=()=>progressFor(data,settings.language,settings.layouts[settings.language]),layout=()=>settings.layouts[settings.language],language=()=>LANGUAGES[settings.language];
const coach=createCoach({getData:()=>data,persist,render,navigate,toast,openDialog,startActivity,startLesson:(group,step)=>{context={group,step};view='lesson';location.hash='lessons';render()},replaceData:value=>{data=ensureLearning(value);settings={...DEFAULT_SETTINGS,...data.settings,layouts:{...DEFAULT_SETTINGS.layouts,...data.settings.layouts}};data.settings=settings;persist({replace:true});applySettings()}});
const onboarding=createOnboarding({getData:()=>data,persist,openDialog,closeDialog,launch:(path,lang,selectedLayout)=>{
 settings.language=lang;settings.layouts[lang]=availableLayouts(lang).includes(selectedLayout)?selectedLayout:LANGUAGES[lang].layout;
 forcedFocus=null;activityPayload=null;
 if(path==='lesson'){context={group:0,step:0};view='lesson';location.hash='lessons';render();}
 else navigate(path==='code'?'code':'practice');
}});
function startActivity(words,ctx){activityPayload={words,ctx};view='activity';location.hash='activity';render()}
function requestHint(){if(!session||session.status==='finished')return;session.hint();hintUntil=performance.now()+3000;paint();$('typingInput')?.focus({preventScroll:true})}
function keyboardSettings(){return {...settings,hintMode:context?.hideHints?'request':settings.hintMode,reveal:performance.now()<hintUntil}}
function todayProgress(progress=p(),lang=settings.language,selectedLayout=layout()){return dailyProgress({history:[...progress.history.filter(r=>!r.metricsVersion||r.metricsVersion<3),...learningFor(data,lang,selectedLayout).activities]})}
function storageError(){toast('Не удалось сохранить прогресс. Результат остаётся на экране: скачай копию или повтори сохранение.');}
function persist(options){return progressStore.save(options).catch(()=>{storageError();return false})}
function toast(message){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').classList.add('show');toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4500)}
function speed(cpm){let v=settings.unit==='wpm'?cpm/5:settings.unit==='cps'?cpm/60:cpm;return Number.isFinite(v)?v.toFixed(settings.unit==='cpm'?0:1):'—'}
const unit=()=>settings.unit.toUpperCase();
function formatDuration(ms){if(ms>0&&ms<1000)return (ms/1000).toFixed(1)+'с';let sec=Math.max(0,Math.round(ms/1000));return `${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}`}
function wordLabel(n){return n%10===1&&n%100!==11?'слово':n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?'слова':'слов'}
function date(at){return new Date(at).toLocaleString('ru-RU',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}
function applySettings(){document.body.dataset.theme=settings.theme;document.documentElement.style.setProperty('--type-size',settings.fontSize+'px');document.documentElement.style.setProperty('--letter-spacing',(settings.letterSpacing||0)+'px');document.body.classList.toggle('reverse',settings.reverse);for(let c of ['line','block','underline'])document.body.classList.toggle('caret-'+c,settings.caretStyle===c);document.documentElement.style.setProperty('--caret-duration',({off:'0s',slow:'.3s',medium:'.15s',fast:'.07s'})[settings.caretSpeed]||'.15s')}
function nav(){
 const items=[['plan','Мой план','01'],['practice','Практика','02'],['code','Код','03'],['lessons','Уроки','04'],['test','Тест','05'],['library','Тексты','06'],['stats','Статистика','07']];
 $('sidebar').innerHTML=`<button class="logo" data-view="practice" aria-label="Десять пальцев — практика"><span class="brand-symbol">&lt;/&gt;</span><span class="brand-copy">Десять пальцев<small>DEV EDITION</small></span></button><div class="nav-section">WORKSPACE</div>${items.map(([id,name,number])=>`<button class="nav-button ${view===id||(view==='lesson'&&id==='lessons')||(view==='activity'&&id==='plan')?'active':''}" data-view="${id}" aria-label="${name}" title="${name}" ${view===id?'aria-current="page"':''}>${icon(id)}<span>${name}</span><small class="nav-number">${number}</small></button>`).join('')}<div class="nav-spacer"></div><div class="sidebar-note"><span class="status-dot"></span> Практика каждый день<small>Точность → ритм → скорость</small></div><button class="nav-button nav-secondary" data-action="themes" aria-label="Цвета" title="Цвета">${icon('theme')}<span>Цвета</span></button><button class="nav-button ${view==='settings'?'active':''}" data-view="settings" aria-label="Настройки" title="Настройки">${icon('settings')}<span>Настройки</span></button><button class="nav-button nav-secondary" data-action="onboarding" aria-label="Обучение" title="Обучение">${icon('play')}<span>Обучение</span></button><button class="nav-button nav-secondary" data-action="help" aria-label="Справка" title="Справка">${icon('help')}<span>Справка</span></button><div class="version">Десять пальцев <span>v4.1</span></div>`;
}
function header(){
 const titles={plan:'Мой план',library:'Мои тексты',activity:context?.title||'Целевая практика',practice:'Практика',code:'Практика кода',lessons:'Уроки слепой печати',lesson:'Уроки слепой печати',test:'Тест скорости',stats:'Личная статистика',settings:'Настройки'};
 const files={plan:'daily-plan.md',practice:'practice.txt',code:CODE_TRACKS[codeTrack].file,lessons:'lessons.md',lesson:'lessons.md',test:'speed-test.txt',stats:'progress.json',library:'my-texts.md',activity:'training.txt',settings:'settings.json'};
 document.title='Десять пальцев · '+titles[view];document.body.dataset.view=view;
 $('header').innerHTML=`<div class="header-location"><span class="workspace-path">~/typing<span>/</span></span><h1>${esc(titles[view])}</h1></div><div class="header-right"><div class="language-switch" role="group" aria-label="Язык для обучения печати">${[['ru','RU'],['en','EN']].map(([id,label])=>`<button data-training-language="${id}" class="${settings.language===id?'active':''}" aria-label="${id==='ru'?'Русский язык для печати':'Английский язык для печати'}" aria-pressed="${settings.language===id}">${label}</button>`).join('')}</div>${settings.language==='fr'?'<button class="soft-button" data-action="language">FR</button>':''}<button class="profile-button" data-view="stats" title="Личная статистика">${icon('stats')}<span>Прогресс</span></button><button class="icon-button mobile-help" data-action="help" aria-label="Как учиться" title="Как учиться">${icon('help')}</button></div><div class="workspace-tabs" aria-label="Быстрые разделы"><button data-view="practice" class="${view==='practice'?'active':''}" ${view==='practice'?'aria-current="page"':''}><span class="file-mark text-file">Aa</span>practice.txt</button><button data-view="code" class="${view==='code'?'active':''}" ${view==='code'?'aria-current="page"':''}><span class="file-mark code-file">{ }</span>${view==='code'?esc(files.code):'playground.js'}</button><span class="current-file">${!['practice','code'].includes(view)?esc(files[view]):esc(LAYOUTS[layout()].name)}</span></div>`;
 if($('footerProfile'))$('footerProfile').textContent=language().code+' · '+LAYOUTS[layout()].name;
}
function selectTrainingLanguage(lang,startPractice=false){
 if(!LANGUAGES[lang])return;if(lang===settings.language&&!startPractice)return;
 session?.pause();settings.language=lang;if(!availableLayouts(lang).includes(settings.layouts[lang]))settings.layouts[lang]=LANGUAGES[lang].layout;
 forcedFocus=null;activityPayload=null;
 if(startPractice||view==='activity'||view==='lesson'||view==='code'&&lang!=='en'){view='practice';location.hash='practice';}
 persist();render();
}
function panelMarkup(){
 const progress=p(),daily=todayProgress(progress),dailyGoal=settings.dailyType==='sessions'?settings.dailyGoal:settings.dailyMinutes,current=settings.dailyType==='sessions'?daily.sessions:Math.floor(daily.minutes),latest=progress.history.at(-1),letter=forcedFocus||targetLetter(progress,settings.language,settings.speedGoal),key=progress.letters[letter];
 return `<section class="practice-panel" aria-label="Прогресс практики"><div class="workspace-heading"><div><p class="eyebrow">// TOUCH TYPING</p><h2>Меньше поиска. Больше потока.</h2><p>Тренируй точность и ритм. Осваивай новые клавиши шаг за шагом.</p></div><span class="profile-badge">${language().code}<span>${esc(LAYOUTS[layout()].name)}</span></span></div><div class="session-stats"><div class="session-stat"><span class="stat-label">Скорость <small>последняя попытка</small></span><strong>${latest?speed(latest.cpm):'—'}<small>${unit()}</small></strong></div><div class="session-stat"><span class="stat-label">Точность <small>последняя попытка</small></span><strong>${latest?Math.round(latest.accuracy):'—'}<small>%</small></strong></div><div class="session-stat"><span class="stat-label">Цель скорости <small>для новой буквы</small></span><strong>${speed(settings.speedGoal)}<small>${unit()}</small></strong></div><div class="session-stat daily-stat"><span class="stat-label">Сегодня <small>${settings.dailyType==='sessions'?'завершённых занятий':'минут практики'}</small></span><strong>${current}<small>/ ${dailyGoal}</small></strong><div class="daily-bar"><i style="width:${Math.min(100,current/dailyGoal*100)}%"></i></div></div></div><div class="letter-progress"><div class="progress-section-heading"><span>ДОСТУПНЫЕ КЛАВИШИ <b>${progress.unlocked} / ${[...language().alphabet].length}</b></span><div class="panel-buttons"><button class="icon-button" data-action="guide" aria-label="Руководство по практике" title="Руководство">${icon('help')}</button><button class="icon-button" data-action="practice-settings" aria-label="Настройки практики" title="Настройки практики">${icon('settings')}</button><button class="icon-button" data-action="regenerate" aria-label="Новое упражнение" title="Новое упражнение">${icon('restart')}</button></div></div><div class="letter-workspace"><div class="letter-grid">${[...language().alphabet].map((c,i)=>{let k=progress.letters[c],score=confidence(k,settings.speedGoal),closed=i>=progress.unlocked;return `<button class="letter ${closed?'closed':(k?.samples||0)<5?'calibrating':'open'} ${c===letter?'target-letter':''}" data-letter="${esc(c)}" aria-label="Буква ${esc(c)}: ${closed?'закрыта':(k?.samples||0)>=5?'освоение '+score+'%':'сбор результатов'}" title="${esc(c.toUpperCase())} · ${closed?'ещё закрыта':(k?.samples||0)>=5?score+'% освоения':(k?.samples||0)+' / 5 образцов'}" style="--mastery:${score}%">${esc(c.toUpperCase())}</button>`}).join('')}</div><div class="focus-letter"><button class="target-key" data-letter="${esc(letter)}">${esc(letter.toUpperCase())}</button><div><span>Сейчас тренируем</span><b>${key?.samples||0} / 5 образцов</b><small>${key?.lastCPM?speed(key.lastCPM)+' '+unit():'Пока собираем данные'}</small></div></div></div></div></section>`;
}
function codeControls(){
 const track=CODE_TRACKS[codeTrack];
 return `<div class="workspace-heading code-heading"><div><p class="eyebrow">// DEVELOPER PRACTICE</p><h2>Код. С клавиатуры.</h2><p>Скобки, операторы, регистр и привычные конструкции.</p></div><span class="profile-badge">EN<span>${esc(LAYOUTS[layout()].name)}</span></span></div><div class="code-tracks" role="group" aria-label="Материал для программистов">${Object.entries(CODE_TRACKS).map(([id,item])=>`<button data-code-track="${id}" class="code-track ${id===codeTrack?'active':''}" aria-label="${esc(item.name)}" aria-pressed="${id===codeTrack}"><span class="track-mark track-${id}">${esc(item.mark)}</span>${esc(item.name)}</button>`).join('')}</div><div class="code-brief"><div><strong>${esc(context.title)}</strong><p>${esc(track.description)}</p></div><button class="outline-button" data-view="library">Свой код →</button></div><p class="material-note">Все буквы и знаки · английская раскладка. Для постепенного изучения букв выбери <button data-start-language="en">English в практике →</button></p>`;
}
function exerciseMarkup(){
 const code=context?.activity==='code',file=code?CODE_TRACKS[context.codeTrack].file:context?.kind==='test'?'speed-test.txt':context?.kind==='lesson'?'lesson.txt':'practice.txt';
 return `<section class="exercise ${code?'code-exercise':''}" aria-label="Упражнение"><div class="editor-surface"><div class="editor-toolbar"><span class="editor-tab"><span class="file-mark ${code?'code-file':'text-file'}">${code?'{ }':'Aa'}</span>${file}</span><span class="editor-mode">${code?'CODE':'WORDS'} · ${language().code}</span><button class="icon-button" data-action="regenerate" aria-label="Новое упражнение в редакторе" title="Новое упражнение">${icon('restart')}</button></div><div id="sessionArea"><div class="stage unfocused" id="stage"><div class="stage-meta"><div class="stage-progress"><i id="exerciseProgress" style="width:0%"></i></div><span id="liveMetric"></span><span class="stage-count" id="stageCount"></span></div><div class="line-gutter" aria-hidden="true"><span>01</span><span>02</span><span>03</span></div><div id="caretOverlay" aria-hidden="true"></div><div class="words" id="words" aria-hidden="true"></div><button class="start-overlay" id="startOverlay">${icon('play')}<span id="startLabel">Нажмите, чтобы начать</span></button><textarea id="typingInput" class="typing-input ${settings.inputVisible?'visible':''}" aria-label="Ввод упражнения" autocomplete="off" autocapitalize="off" spellcheck="false" rows="1"></textarea></div><p class="input-message" id="inputMessage" role="status"></p><div class="exercise-actions"><button data-action="hint" title="Помощь · F1">${icon('help')}<span>подсказка</span><kbd>F1</kbd></button><button data-action="pause" title="Пауза">${icon('pause')}<span id="pauseActionLabel">пауза</span><kbd>Esc</kbd></button><button data-action="repeat">${icon('restart')}повторить</button><button data-action="regenerate">${icon('arrow')}новый текст</button></div></div><div class="editor-status"><span id="sessionState" class="session-state"><i class="status-dot"></i>READY</span><span>Пробел → слово <span class="status-divider">/</span> Backspace → исправить</span><span>${session.words.length} ${wordLabel(session.words.length)}</span></div></div>${keyboardMarkup(layout())}</section>`;
}
function testControls(){return `<div class="control-panel"><div class="segmented" aria-label="Режим теста">${[['words','слова'],['time','время'],['quote','цитата']].map(([v,n])=>`<button data-test-mode="${v}" class="${settings.testMode===v?'active':''}" aria-pressed="${settings.testMode===v}">${n}</button>`).join('')}</div>${settings.testMode==='quote'?'':`<div class="segmented" aria-label="${settings.testMode==='time'?'Продолжительность':'Количество слов'}">${(settings.testMode==='time'?[15,30,60,120]:[10,25,50,100]).map(n=>`<button data-test-amount="${n}" class="${n===(settings.testMode==='time'?settings.testTime:settings.testWords)?'active':''}" aria-pressed="${n===(settings.testMode==='time'?settings.testTime:settings.testWords)}">${settings.testMode==='time'?n<60?n+'с':n/60+'м':n}</button>`).join('')}<button data-action="custom-test" title="Своё значение" aria-label="Своё значение">${![15,30,60,120].includes(settings.testTime)&&settings.testMode==='time'?esc(settings.testTime)+'с':settings.testMode==='words'&&![10,25,50,100].includes(settings.testWords)?esc(settings.testWords):'…'}</button></div>`}<button class="soft-button" data-action="language">${icon('globe')}${language().name}</button>${settings.testMode!=='quote'?`<button class="soft-button ${settings.punctuation?'active':''}" data-action="punctuation" aria-pressed="${settings.punctuation}">пунктуация</button>`:''}</div>`}
function lessonThreshold(ctx){return{cpm:ctx.step===0?0:ctx.step<3?60:120,accuracy:95}}
function makeSession(words,ctx){wordView?.destroy();wordView=null;context={...ctx,lang:settings.language,layout:layout(),rules:{spaceToFinish:settings.spaceToFinish,noWayBack:settings.noWayBack,speedGoal:settings.speedGoal}};finishedHandled=false;focused=false;session=new TypingSession(words,{mode:ctx.mode||'words',seconds:ctx.seconds||0,spaceToFinish:settings.spaceToFinish,noWayBack:settings.noWayBack,strictTest:!!ctx.strictTest||ctx.kind==='test'});hintUntil=0;}
function render(){if(view==='code'&&settings.language!=='en'){settings.language='en';forcedFocus=null;persist();}wordView?.destroy();wordView=null;document.body.classList.remove('typing-focus');nav();header();applySettings();if(view==='activity'&&activityPayload){makeSession(activityPayload.words,{kind:'activity',...activityPayload.ctx});header();$('content').innerHTML=`<div class="session-meta"><button class="soft-button" data-view="plan">← Мой план</button><strong>${esc(context.title)}</strong><span>${language().code} · ${esc(LAYOUTS[layout()].name)}</span></div><div class="help-tip">${esc(context.reason||'')}</div>`+exerciseMarkup();bindSession()}else if(view==='practice'){let chars=[...language().alphabet].slice(0,p().unlocked).join('');let material=practiceMaterial(settings.language,chars,forcedFocus||targetLetter(p(),settings.language,settings.speedGoal));makeSession(material.words,{kind:'practice',material:material.type,materialVersion:2});$('content').innerHTML=panelMarkup()+`<p class="material-note">${material.type==='drill'?'Сочетания клавиш: с этим набором ещё нет слов.':esc(material.note)}</p>`+exerciseMarkup();bindSession()}else if(view==='code'){const item=codeExercise(codeTrack,++codeRound);makeSession(item.words,{kind:'activity',activity:'code',codeTrack,title:item.title,contentId:'code-'+codeTrack+'-'+item.index,reason:CODE_TRACKS[codeTrack].description});header();$('content').innerHTML=codeControls()+exerciseMarkup();bindSession()}else if(view==='test'){let words=settings.testMode==='quote'?language().quotes[Math.floor(Math.random()*language().quotes.length)].split(' '):generateWords({lang:settings.language,count:settings.testMode==='time'?Math.max(400,Math.min(10000,settings.testTime*12)):settings.testWords,punctuation:settings.punctuation});makeSession(words,{kind:'test',mode:settings.testMode==='time'?'time':'words',testMode:settings.testMode,seconds:settings.testMode==='time'?settings.testTime:0,wordLimit:settings.testWords});$('content').innerHTML=testControls()+exerciseMarkup();bindSession()}else if(view==='lesson'){let info=lessonInfo(context.group,context.step,layout());makeSession(lessonWords(info,settings.language),{kind:'lesson',...info});$('content').innerHTML=`<div class="session-meta"><button class="soft-button" data-view="lessons">← Список уроков</button><strong>${context.group+1}.${context.step+1} · ${STEP_NAMES[context.step]}</strong><span>цель ${lessonThreshold(context).cpm||'спокойный темп'}${lessonThreshold(context).cpm?' CPM':''} · 95%</span></div><div class="help-tip">${context.step<=2||!wordPool(settings.language,info.learned).length?'Это сочетания клавиш, а не слова. ':''}Клавиши ${esc(info.fresh.toUpperCase().split('').join(' · '))}. Возвращай пальцы на домашний ряд. Стремись к точности 95% и выше.</div>`+exerciseMarkup();bindSession()}else{session=null;context=null;if(view==='plan')$('content').innerHTML=coach.planMarkup();if(view==='library')$('content').innerHTML=coach.libraryMarkup();if(view==='lessons')$('content').innerHTML=courseMarkup();if(view==='stats')$('content').innerHTML=statsMarkup();if(view==='settings'){$('content').innerHTML=settingsMarkup();settingsInDialog=false;}}}
function navigate(next){if(session?.status==='running')session.pause();if(next!=='practice')forcedFocus=null;view=next;location.hash=next;render();}
function bindSession(){
 let input=$('typingInput'),owned=session;
 wordView=new WordView($('words'),owned,{syntax:context.activity==='code',onLayout:()=>{if(session===owned)paint()}});
 input.addEventListener('focus',()=>{if(session!==owned)return;focused=true;owned.resume();paint()});
 input.addEventListener('blur',()=>{if(session!==owned)return;focused=false;owned.pause();paint()});
 bindTypingInput(input,{getSession:()=>session===owned?owned:null,getSettings:()=>settings,paint,showHint:requestHint,message:text=>{if(session===owned&&$('inputMessage'))$('inputMessage').textContent=text},press:char=>pressKeyboard($('content'),context.layout,char,settings)});
 $('stage').addEventListener('click',()=>{if(session===owned&&owned.status!=='finished')input.focus({preventScroll:true})});paint();
}
function paint(){
 if(!session)return;if(session.status==='finished'){if(!finishedHandled)finishSession();return}if(!$('words')||!wordView)return;
 wordView.update(settings);let rect=wordView.caretRect(),overlay=$('caretOverlay');
 if(rect&&overlay){let stageRect=$('stage').getBoundingClientRect(),underline=settings.caretStyle==='underline';overlay.style.left=(rect.left-stageRect.left)+'px';overlay.style.top=(rect.top-stageRect.top+rect.height*(underline?.91:.12))+'px';overlay.style.height=(underline?2:rect.height*.76)+'px';overlay.style.width=(settings.caretStyle==='line'?2:rect.width)+'px';overlay.style.opacity=settings.caretStyle==='block'?'.3':'1';}
 if($('sessionState'))$('sessionState').innerHTML='<i class="status-dot"></i>'+({idle:'READY',running:'TYPING',paused:'PAUSED'}[session.status]||'READY');$('stage').classList.toggle('unfocused',!focused||session.status==='paused');$('startLabel').textContent=session.status==='paused'?'Пауза · нажмите для продолжения':'Нажмите, чтобы начать';
 let m=session.metrics(),timeMode=session.options.mode==='time',progress=timeMode?session.duration/(session.options.seconds*1000):session.word/session.words.length;
 $('exerciseProgress').style.width=Math.min(100,progress*100)+'%';$('stageCount').textContent=timeMode?formatDuration(Math.max(0,session.options.seconds*1000-session.duration)):`${session.word} / ${session.words.length}`;
 $('liveMetric').textContent=session.status==='idle'?'':`${speed(m.cpm)} ${unit()} · ${Math.round(m.accuracy)}%`;$('pauseActionLabel').textContent=session.status==='paused'?'продолжить':'пауза';
 updateKeyboard($('content'),context.layout,focused&&session.status!=='paused'?session.nextChar:null,keyboardSettings());document.body.classList.toggle('typing-focus',settings.focus&&session.status==='running'&&focused);
}
async function finishSession(){
 finishedHandled=true;document.body.classList.remove('typing-focus');wordView?.destroy();
 const owned=session,ctx=context,result={...owned.result,at:Date.now(),kind:ctx.kind,mode:ctx.testMode||'words',seconds:ctx.seconds||0,wordLimit:ctx.wordLimit||owned.words.length,materialVersion:ctx.materialVersion||1};
 let outcome;
 try{outcome=await progressStore.complete(result,ctx)}catch(error){outcome=applyCompletion(data,{...result,savedLocally:false},ctx);outcome.saved=false;}
 if(session!==owned)return;owned.result={...outcome.result,savedLocally:outcome.saved};showResult(owned.result);
 if(!outcome.saved)storageError();
 else if(outcome.opened)toast(`Новая буква: ${outcome.opened.toUpperCase()}! Она появится в следующем задании.`);
}
function showResult(result){
 if($('sessionState'))$('sessionState').innerHTML='<i class="status-dot"></i>FINISHED';
 $('sessionArea').innerHTML=resultMarkup(result)+(context.kind==='activity'&&context.activity!=='code'?coach.resultExtra(result,context):'');
 updateKeyboard($('content'),context.layout,null,keyboardSettings());
 if(view==='practice')document.querySelector('.practice-panel').outerHTML=panelMarkup();
}
async function retrySave(){
 if(!session?.result)return;const owned=session,ctx=context,outcome=await progressStore.complete(owned.result,ctx).catch(()=>null);
 if(session!==owned)return;if(outcome?.saved){owned.result={...outcome.result,savedLocally:true};showResult(owned.result);toast('Результат сохранён.')}else storageError();
}
function practiceSampleMarkup(r){
 const sample=r.practiceSample;if(!sample)return '';
 const reasons={accuracy:'точность ввода и с первого раза должна быть от 95%',unfinished:'допечатай и исправь все слова',speed:`скорость всего задания должна быть от ${speed(sample.floor)} ${unit()}`,measurement:'недостаточно измерений скорости'};
 const accepted=sample.accepted.map(c=>esc(c.toUpperCase())).join(' · '),observed=sample.observed||Object.keys(r.keys||{}),rejected=observed.filter(c=>!sample.accepted.includes(c));
 const title=accepted?`Засчитаны образцы: ${accepted}`:'Образцы не засчитаны';
 const explanation=sample.reasons.length?sample.reasons.map(reason=>reasons[reason]).filter(Boolean).join('; '):rejected.length?`Буквы ${rejected.map(c=>esc(c.toUpperCase())).join(' · ')} пока без образца: скорость ниже 70% цели, точность ниже 95% или меньше двух верных вводов с измеренным интервалом`:'';
 return `<div class="sample-status ${accepted?'sample-accepted':''}"><strong>${title}</strong>${explanation?`<p>${explanation}.</p>`:''}<small>Порог образца: ${speed(sample.floor)} ${unit()} · точность от 95%. Новая буква открывается после пяти образцов каждой доступной буквы и достижения полной цели ${speed(sample.goal)} ${unit()}.</small></div>`;
}
function resultMarkup(r){let failed=context.kind==='lesson'&&!r.passed,title=context.kind==='practice'?'Практика завершена':failed?r.lessonSuccess?'Закрепим шаг':'Попробуй ещё раз':'Готово!',hint=context.kind==='practice'?'Результат сохранён. Следующее задание начнётся по кнопке ниже.':context.kind==='lesson'?r.passed?'Шаг пройден. Можно переходить дальше.':r.lessonSuccess?'Хорошая попытка. Закрепи шаг ещё в одном новом упражнении.':'Попробуй спокойнее: цель — точность 95%. Успехи уже пройденных шагов сохраняются.':'Результат сохранён в твою историю.',misspelled=[...new Set(r.misspelled)];return `<div class="result"><div class="result-header"><div><h2>${title}</h2><p>${r.savedLocally===false?'Результат пока доступен только на этом экране.':hint}</p></div><span class="badge">${LANGUAGES[context.lang].code} · ${context.kind==='practice'?'практика':context.kind==='lesson'?'урок':context.kind==='activity'?context.activity==='code'?esc(CODE_TRACKS[context.codeTrack].name):context.activity==='control'?'контроль':context.activity==='diagnostic'?'диагностика':context.activity==='custom'?'мой текст':'практика':context.testMode==='time'?context.seconds+'с':context.testMode==='quote'?'цитата':'слова'}</span></div><div class="result-metrics"><div class="result-metric"><strong>${speed(r.cpm)}</strong><small>${unit()} · скорость</small></div><div class="result-metric"><strong>${Math.round(r.accuracy)}%</strong><small>точность ввода</small></div><div class="result-metric"><strong>${formatDuration(r.duration)}</strong><small>время набора</small></div></div><div class="result-detail"><span>Слова <b>${r.correctWords}</b> / <b>${r.incorrectWords}</b></span><span>Символы <b>${r.correct}</b> верно · <b>${r.incorrect+r.missed+r.extra}</b> осталось исправить</span><span>Ошибок ввода <b>${r.errors}</b></span><span>С первого раза <b>${Math.round(r.firstAttemptAccuracy)}%</b></span><span>Финал <b>${Math.round(r.finalAccuracy)}%</b></span><span>Исправлений <b>${r.corrections||0}</b></span><span>Помощь <b>${r.hints||0}</b></span><span title="WPM = CPM / 5">${Math.round(r.cpm)} CPM · ${(r.cpm/5).toFixed(1)} WPM</span></div>${context.kind==='practice'?practiceSampleMarkup(r):''}${r.comparable===false?'<p class="comparison-note">Была пауза: это учебная попытка. В рекорд и независимое сравнение она не входит.</p>':''}${misspelled.length?`<div class="errors-list">Слова для повторения: ${misspelled.slice(0,12).map(w=>`<span>${esc(w)}</span>`).join('')}</div>`:''}${r.savedLocally===false?'<div class="save-status" role="alert">Сохранение не удалось. Не закрывай эту страницу до повторного сохранения или скачивания копии.<div class="coach-actions"><button class="primary-button" data-action="retry-save">Повторить сохранение</button><button class="outline-button" data-coach="export">Скачать резервную копию</button></div></div>':''}<div class="result-actions">${context.activity==='code'?'<button class="primary-button" data-action="regenerate">Следующий фрагмент →</button>':context.kind==='activity'?'<button class="outline-button" data-view="plan">Мой план</button>':context.kind==='lesson'&&r.passed?'<button class="primary-button" data-action="next-lesson">Следующий шаг →</button>':'<button class="primary-button" data-action="regenerate">Следующее задание →</button>'}<button class="outline-button" data-action="repeat">Повторить текст</button>${context.kind!=='practice'&&misspelled.length?'<button class="outline-button" data-action="mistakes">Работа над ошибками</button>':''}${context.kind!=='practice'?'<button class="outline-button" data-action="result-image">Сохранить картинку</button>':''}</div><p class="result-stays">Результат останется здесь, пока ты сам не выберешь следующее действие.</p></div>`}
function courseMarkup(){let completed=0;for(let g=0;g<LESSON_GROUPS.length;g++)for(let st=0;st<LESSON_GROUPS[g][1];st++)if(p().lessons[`${layout()}:${g}:${st}`]?.passed)completed++;let nextFound=false;return `<div class="course-top"><div><h2>Освой каждую клавишу</h2><p>11 групп · 81 шаг · ${LAYOUTS[layout()].name}</p></div><button class="soft-button" data-action="language">${icon('globe')}${language().name}</button><span class="badge">${completed} / 81 · ${Math.round(completed/81*100)}%</span></div><div class="course-progress"><i style="width:${completed/81*100}%"></i></div><p class="muted" style="font-size:12px">Начни с первой группы. Новые клавиши постепенно соединяются с уже изученными.</p>${LESSON_GROUPS.map(([keys,count],g)=>`<section class="lesson-group"><h3>${g+1}. Клавиши <b>${esc(mapPhysicalKeys(keys,layout()).toUpperCase().split('').join(' · '))}</b></h3><div class="steps">${Array.from({length:count},(_,st)=>{let r=p().lessons[`${layout()}:${g}:${st}`],status=r?.passed?'completed':r?'failed':!nextFound?'available':'';if(status==='available')nextFound=true;return `<button class="step-button ${status}" data-group="${g}" data-step="${st}" title="${STEP_NAMES[st]}${r?' · '+Math.round(r.cpm)+' CPM · '+Math.round(r.accuracy)+'%':''}" aria-label="Группа ${g+1}, шаг ${st+1}: ${STEP_NAMES[st]}${r?.passed?', пройден':''}">${r?.passed?'✓':st+1}${r?`<small>${Math.round(r.accuracy)}%</small>`:''}</button>`}).join('')}</div></section>`).join('')}<div class="lesson-legend"><span><i></i>Следующий шаг</span><span><i style="background:var(--success)"></i>Пройден</span><span><i style="background:var(--error)"></i>Можно улучшить</span></div><div class="help-tip">Для новых шагов нужны две последовательные уверенные попытки с точностью 95%. На знакомстве с клавишами ограничения скорости нет; далее цель постепенно растёт до 120 CPM. Прежние пройденные шаги сохранены.</div>`}
function history(){return [...p().history,...p().tests,...(p().lessonHistory||[]),...learningFor(data,settings.language,layout()).activities.filter(r=>!['practice','lesson','test'].includes(r.activity))].sort((a,b)=>a.at-b.at)}
function chartMarkup(h){let values=h.slice(-30);if(values.length<2)return '<p class="muted" style="padding:30px 0;text-align:center;font-size:12px">График появится после двух завершённых занятий.</p>';let max=Math.max(100,...values.map(r=>r.cpm))*1.1;let points=values.map((r,i)=>`${40+i/(values.length-1)*810},${170-r.cpm/max*140}`).join(' ');return `<svg class="history-chart" viewBox="0 0 890 210" role="img" aria-label="Скорость последних ${values.length} занятий"><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="var(--accent)" stop-opacity=".2"/><stop offset="1" stop-color="var(--accent)" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>`<line x1="40" x2="850" y1="${170-i*45}" y2="${170-i*45}" stroke="var(--line)"/><text x="0" y="${174-i*45}" fill="var(--muted)" font-size="10">${speed(max*i*45/140)}</text>`).join('')}<polygon points="40,170 ${points} 850,170" fill="url(#chartFill)"/><polyline points="${points}" fill="none" stroke="var(--accent)" stroke-width="2.5" stroke-linejoin="round"/>${values.map((r,i)=>`<circle cx="${40+i/(values.length-1)*810}" cy="${170-r.cpm/max*140}" r="3" fill="var(--accent)"><title>${date(r.at)} · ${speed(r.cpm)} ${unit()} · ${Math.round(r.accuracy)}%</title></circle>`).join('')}<text x="40" y="200" fill="var(--muted)" font-size="10">${date(values[0].at)}</text><text x="850" y="200" text-anchor="end" fill="var(--muted)" font-size="10">${date(values.at(-1).at)}</text></svg>`}
function statsMarkup(){let h=history(),avg=h.length?h.reduce((s,r)=>s+r.cpm,0)/h.length:0,acc=h.length?h.reduce((s,r)=>s+r.accuracy,0)/h.length:0,duration=h.reduce((s,r)=>s+r.duration,0),records=new Map();for(let r of p().tests){if(r.mode==='mistakes'||r.comparable===false)continue;let name=r.mode==='time'?`${r.seconds}с`:r.mode==='quote'?'Цитаты':`${r.wordLimit} ${wordLabel(r.wordLimit)}`,old=records.get(name);if(!old||r.cpm>old.cpm)records.set(name,r)}return `<div class="course-top"><div><h2>Твой прогресс</h2><p>${language().name} · ${esc(LAYOUTS[layout()].name)}</p></div><button class="soft-button" data-action="language">${icon('globe')}${language().name}</button></div><div class="stats-summary"><div><b>${h.length}</b><small>завершённых занятий</small></div><div><b>${h.length?speed(avg):'—'}</b><small>среднее за занятие · ${unit()}</small></div><div><b>${h.length?Math.round(acc)+'%':'—'}</b><small>средняя точность</small></div><div><b>${Math.round(duration/60000)}</b><small>минут практики</small></div></div>${!h.length?'<div class="empty-state"><p>Пока нет завершённых занятий. Начни практику — каждый результат останется здесь.</p><button class="primary-button" data-view="practice">Начать практику</button></div>':''}<div class="chart-panel"><h3>Скорость последних занятий · ${unit()}</h3><p class="storage-note">Материал и сложность различаются. Для проверки роста используй независимые тексты ниже.</p>${chartMarkup(h)}</div>${coach.skillsMarkup()}<section class="stat-section"><h3>Личные рекорды</h3>${records.size?`<div class="table-wrap"><table><thead><tr><th>Режим</th><th>${unit()}</th><th>Точность</th><th>Дата</th></tr></thead><tbody>${[...records].map(([name,r])=>`<tr><td>${name}</td><td>${speed(r.cpm)}</td><td>${Math.round(r.accuracy)}%</td><td>${date(r.at)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="storage-note">Пройди тест по словам, времени или цитате, чтобы установить первый рекорд.</p>'}</section><section class="stat-section"><h3>Освоение букв · ${p().unlocked} / ${[...language().alphabet].length}</h3><div class="table-wrap"><table class="letters-table"><thead><tr><th>Буква</th><th>Последняя</th><th>Лучшая</th><th>Освоение</th><th>Образцов</th></tr></thead><tbody>${[...language().alphabet].slice(0,p().unlocked).map(c=>{let k=p().letters[c];return `<tr><td class="letter-cell">${esc(c.toUpperCase())}</td><td>${k?speed(k.lastCPM)+' '+unit():'—'}</td><td>${k?speed(k.topCPM)+' '+unit():'—'}</td><td>${confidence(k,settings.speedGoal)}%</td><td>${k?.samples||0}</td></tr>`}).join('')}</tbody></table></div></section>${h.length?`<section class="stat-section"><h3>История занятий</h3><div class="table-wrap"><table><thead><tr><th>Дата</th><th>Режим</th><th>${unit()}</th><th>Точность</th><th>Время</th></tr></thead><tbody>${h.slice(-30).reverse().map(r=>`<tr><td>${date(r.at)}</td><td>${r.kind==='practice'?'Практика':r.kind==='lesson'?'Урок':r.kind==='activity'?esc(r.title||'Тренировка'):r.mode==='mistakes'?'Ошибки':'Тест'}</td><td>${speed(r.cpm)}</td><td>${Math.round(r.accuracy)}%</td><td>${formatDuration(r.duration)}</td></tr>`).join('')}</tbody></table></div></section>`:''}<p class="storage-note">История и настройки хранятся в этом браузере отдельно для каждого языка. Скорость WPM рассчитывается как CPM ÷ 5.${Object.keys(data.legacyLessons).length?` Результаты прежнего курса сохранены: ${Object.keys(data.legacyLessons).length} из 7 уроков.`:''}</p>`}
const switchField=(key,label,description='')=>`<div class="setting-row"><label class="setting-label" for="setting-${key}">${label}${description?`<small>${description}</small>`:''}</label><input class="switch" type="checkbox" id="setting-${key}" aria-label="${esc(label)}" data-setting="${key}" ${settings[key]?'checked':''}></div>`;
const selectField=(key,label,choices,description='')=>`<div class="setting-row"><label class="setting-label" for="setting-${key}">${label}${description?`<small>${description}</small>`:''}</label><select id="setting-${key}" aria-label="${esc(label)}" data-setting="${key}">${choices.map(([v,n])=>`<option value="${esc(v)}" ${settings[key]===v?'selected':''}>${esc(n)}</option>`).join('')}</select></div>`;
const numberField=(key,label,value,min,max,description='')=>`<div class="setting-row"><label class="setting-label" for="setting-${key}">${label}${description?`<small>${description}</small>`:''}</label><input id="setting-${key}" aria-label="${esc(label)}" type="number" min="${min}" max="${max}" step="${key==='speedGoal'&&settings.unit!=='cpm'?'0.1':'1'}" value="${value}" data-setting="${key}"></div>`;
function settingsMarkup(){let tabs=[['practice','Практика'],['appearance','Внешний вид'],['behavior','Поведение'],['data','Данные']];return `<div class="settings-tabs" role="group" aria-label="Раздел настроек">${tabs.map(([v,n])=>`<button class="${settingsTab===v?'active':''}" data-settings-tab="${v}">${n}</button>`).join('')}</div>${settingsTab==='data'?coach.dataMarkup():settingsTab==='practice'?`<section class="setting-section"><h3>Основные</h3>${selectField('language','Язык упражнений',Object.entries(LANGUAGES).map(([id,l])=>[id,l.name]),'Язык интерфейса — русский. У каждого языка и раскладки отдельный профиль.')}<div class="setting-row"><label class="setting-label" for="setting-layout">Раскладка клавиатуры<small>Выбери ту же раскладку, которая включена на компьютере.</small></label><select id="setting-layout" aria-label="Раскладка клавиатуры" data-setting="layout">${availableLayouts(settings.language).map(v=>`<option value="${esc(v)}" ${layout()===v?'selected':''}>${esc(LAYOUTS[v].name)}</option>`).join('')}</select></div>${selectField('unit','Единицы скорости',[['cpm','CPM'],['wpm','WPM'],['cps','CPS']],'CPM — знаки в минуту. WPM = CPM ÷ 5. CPS = CPM ÷ 60.')}${numberField('speedGoal','Целевая скорость · '+unit(),speed(settings.speedGoal),settings.unit==='cpm'?1:.1,settings.unit==='cpm'?3000:600,'Образец: от 70% цели, точность от 95%, весь текст исправлен. Новая буква: пять образцов для каждой доступной буквы и её скорость от 100% цели.')}</section><section class="setting-section"><h3>Дневная цель</h3>${selectField('dailyType','Считать по',[['sessions','Занятиям'],['time','Времени']])}${settings.dailyType==='sessions'?numberField('dailyGoal','Тренировок в день',settings.dailyGoal,1,200):numberField('dailyMinutes','Минут в день',settings.dailyMinutes,1,300)}</section>`:settingsTab==='appearance'?`<section class="setting-section"><h3>Текст и курсор</h3><p class="storage-note">Текст закреплён на экране. Пробел перемещает только курсор; длинные упражнения переходят к следующей странице после завершения текущей.</p>${numberField('fontSize','Размер шрифта',settings.fontSize,18,48)}${numberField('letterSpacing','Расстояние между символами',settings.letterSpacing||0,0,5)}${selectField('caretStyle','Вид курсора',[['line','Линия'],['block','Блок'],['underline','Подчёркивание']])}${switchField('reverse','Инверсия цвета текста','Меняет оттенки набранных и ещё не набранных символов.')}<div class="settings-preview"><span>Печатай</span><i></i> спокойно и уверенно.</div></section><section class="setting-section"><h3>Клавиатура</h3>${switchField('keyboard','Показывать клавиатуру')}${switchField('hands','Показывать руки','Подсказка по стандартной карте пальцев.')}${switchField('handsMotion','Движение рук','Выключи, если предпочитаешь спокойную статичную подсказку.')}${selectField('hintMode','Помощь',[['always','Всегда'],['request','По запросу · F1'],['off','Скрыта · F1 для помощи']],'Запросы учитываются отдельно от ошибок.')}<div class="setting-row"><span class="setting-label">Цветовая тема</span><button class="outline-button" data-action="themes">Выбрать тему</button></div></section>`:`<section class="setting-section"><h3>Набор текста</h3>${switchField('spaceToFinish','Пробел для завершения','В конце последнего слова нажми пробел. Если выключено — упражнение завершится на последней букве.')}${switchField('noWayBack','Нет пути назад','Запрещает удалять символы и возвращаться к предыдущим словам.')}${switchField('focus','Режим фокуса','Во время набора интерфейс приглушается, чтобы не отвлекать тебя.')}${switchField('hideExtra','Скрывать лишние символы','Ошибки за границей слова учитываются даже при скрытии.')}${switchField('inputVisible','Показывать поле ввода','Отдельное поле для текущего слова.')}<div class="help-tip">Исправленная ошибка остаётся в статистике. Backspace удаляет символ, Ctrl / ⌘ + Backspace — слово. Esc ставит занятие на паузу.</div></section>`}<p class="storage-note">Изменения сохраняются автоматически.</p>`}
function openDialog(title,body,extra=''){session?.pause();document.body.classList.remove('typing-focus');$('dialog').innerHTML=`<div class="dialog-header"><h2>${title}</h2><button data-action="close-dialog" aria-label="Закрыть">${icon('close')}</button></div>${body}${extra}`;$('dialog').showModal()}
function openSettings(tab='practice'){settingsTab=tab;settingsInDialog=true;resetAfterSettings=false;openDialog('Настройки',settingsMarkup());}
function closeDialog(){if(onboarding.active){onboarding.dismiss();return;}let wasSettings=settingsInDialog;$('dialog').close();settingsInDialog=false;if(resetAfterSettings){resetAfterSettings=false;if(view==='lesson')view='lessons';if(view==='activity'){view='plan';activityPayload=null;}render()}else if(wasSettings&&session){paint()} }
function changeSetting(el){let key=el.dataset.setting,value=el.type==='checkbox'?el.checked:el.value;if(el.type==='number'){value=Number(value);if(!Number.isFinite(value)||value<Number(el.min)||value>Number(el.max)){el.value=key==='speedGoal'?speed(settings.speedGoal):settings[key];toast('Укажи значение от '+el.min+' до '+el.max+'.');return}}
 if(key==='layout'){if(!availableLayouts(settings.language).includes(value))return;settings.layouts[settings.language]=value;resetAfterSettings=true}else if(key==='speedGoal'){settings.speedGoal=Math.round(value*(settings.unit==='wpm'?5:settings.unit==='cps'?60:1))}else{settings[key]=value;if(key==='language'){if(!availableLayouts(value).includes(settings.layouts[value]))settings.layouts[value]=LANGUAGES[value].layout;forcedFocus=null;resetAfterSettings=true}}
 if(session&&session.status!=='finished'&&['spaceToFinish','noWayBack'].includes(key))resetAfterSettings=true;persist();applySettings();if(['dailyType','language','unit','wordsView'].includes(key)){if(settingsInDialog)$('dialog').innerHTML=`<div class="dialog-header"><h2>Настройки</h2><button data-action="close-dialog" aria-label="Закрыть">${icon('close')}</button></div>`+settingsMarkup();else $('content').innerHTML=settingsMarkup()}if(!settingsInDialog&&view==='settings')header();if(!resetAfterSettings&&session&&session.status!=='finished'){let input=$('typingInput');input?.classList.toggle('visible',settings.inputVisible);$('words')?.classList.toggle('tape',settings.wordsView==='tape');paint()} }
function themes(){settingsInDialog=false;openDialog('Цвета',`<div class="theme-options">${[['dark','Night Editor','#101317','#70e4b4','#a9a6ff','#ff7f8d'],['light','Day Editor','#f6f8fa','#087956','#635bc8','#bc4057'],['warm','Тёплая','#f1eee7','#9d733e','#8e9373','#b66e64']].map(([id,name,bg,a,b,c])=>`<button class="theme-option ${settings.theme===id?'active':''}" data-theme="${id}"><div class="theme-swatch" style="background:${bg}"><i style="background:${a}"></i><i style="background:${b}"></i><i style="background:${c}"></i></div>${name}<small>${settings.theme===id?'Выбрана':'Нажми, чтобы применить'}</small></button>`).join('')}</div>`)}
const guide=[['Практика подстраивается под тебя','Начни с пяти доступных букв. В заданиях используются только знакомые клавиши, а новые открываются постепенно.','О Е А И Н'],['Буква, которой нужно внимание','Тренажёр выбирает новую или самую слабую букву и включает её примерно в половину слов; остальные закрепляют знакомые клавиши. Можно выбрать доступную букву вручную.','E E E'],['Как открываются новые буквы','Образец засчитывается от 70% цели при точности ввода и с первого раза от 95%. Все слова должны быть допечатаны и исправлены. Нужны минимум два верных ввода буквы и измеренный интервал. Скорость буквы не может быть выше скорости всего задания. Для новой буквы: по пять образцов каждой доступной буквы и её последняя качественная попытка от 100% цели.','5 → +1'],['Смотри на экран','Подсветка клавиши и движение пальца показывают, чем нажать. После нажатия возвращай пальцы на домашний ряд. На А и О (F и J) есть выступы.','Ф Ы В А · О Л Д Ж'],['Ошибки можно исправить','Используй Backspace для символа и Ctrl / ⌘ + Backspace для слова. Ошибка останется в статистике — так ты увидишь, над чем работать.','←'],['Занимайся понемногу каждый день','Выбери дневную цель по времени или количеству тренировок. Начни с 10–15 минут, не торопись и стремись к точности 95% и выше.','10–15 мин']];
function showGuide(){let [title,text,illustration]=guide[guideStep];if(guideStep===0)illustration=language().alphabet.slice(0,5).toUpperCase().split('').join(' · ');if(guideStep===3){let home=LAYOUTS[layout()].rows[1];illustration=home.slice(0,4).toUpperCase()+' · '+home.slice(6,10).toUpperCase();text='Подсветка клавиши и движение пальца показывают, чем нажать. Возвращай пальцы на домашний ряд. На клавишах указательных пальцев есть выступы: для выбранной раскладки это '+home[3].toUpperCase()+' и '+home[6].toUpperCase()+'.'}settingsInDialog=false;openDialog('Руководство по практике',`<div class="guide-count">ШАГ ${guideStep+1} / ${guide.length}</div><h2>${title}</h2><div class="guide-illustration">${esc(illustration)}</div><div class="help-copy"><p>${text}</p></div>`,`<div class="dialog-footer"><button class="outline-button" data-guide="back" ${guideStep===0?'disabled':''}>← Назад</button><button class="primary-button" data-guide="next">${guideStep===guide.length-1?'Начать практику':'Дальше →'}</button></div>`)}
function help(){settingsInDialog=false;openDialog('Как научиться печатать десятью пальцами',`<div class="help-copy"><h3>Поставь руки на домашний ряд</h3><p>В русской раскладке левая рука лежит на <b>Ф Ы В А</b>, правая — на <b>О Л Д Ж</b>. В английской — <b>A S D F</b> и <b>J K L ;</b>. Указательные пальцы находят выступы на А и О (F и J), большие нажимают пробел.</p><p>Для выбранной раскладки ${esc(LAYOUTS[layout()].name)} домашний ряд: <b>${esc(LAYOUTS[layout()].rows[1].slice(0,4).toUpperCase().split('').join(' '))}</b> слева и <b>${esc(LAYOUTS[layout()].rows[1].slice(6,10).toUpperCase().split('').join(' '))}</b> справа.</p><h3>Личный маршрут</h3><p>В разделе <b>Мой план</b> выбери цель, пройди короткую диагностику и получи следующий шаг. <b>Тексты</b> содержат упражнения с Shift, цифрами и рабочими фрагментами. Свои тексты обрабатываются локально.</p><h3>Выбери способ обучения</h3><p><b>Уроки</b> знакомят с клавишами по шагам. <b>Практика</b> подбирает слова под слабые буквы. <b>Тест</b> измеряет навык по времени, словам или цитате. <b>Статистика</b> показывает историю и личные рекорды.</p><h3>Не торопись</h3><p>Смотри на экран и пользуйся подсказками рук. Расслабь плечи и кисти. Если устаёшь — сделай перерыв. Точность 95% и выше важнее высокой скорости.</p><h3>Клавиши управления</h3><p><b>Пробел</b> — следующее слово. <b>Backspace</b> — исправить символ. <b>Ctrl / ⌘ + Backspace</b> — удалить слово. <b>Esc</b> — пауза. После упражнения результат остаётся открытым. Выбери кнопку под ним; с клавиатуры используй Tab и Enter.</p><div class="coach-actions"><button class="primary-button" data-action="onboarding">Пройти обучение →</button><button class="outline-button" data-action="guide">Правила практики</button></div></div>`)}
function letterDialog(letter){let index=[...language().alphabet].indexOf(letter),open=index<p().unlocked,key=p().letters[letter],score=confidence(key,settings.speedGoal);settingsInDialog=false;openDialog('Буква '+esc(letter.toUpperCase()),`<div class="letter-stage">${esc(letter.toUpperCase())}</div><div class="letter-detail"><div><b>${key?speed(key.lastCPM):'—'}</b><small>последняя · ${unit()}</small></div><div><b>${key?speed(key.topCPM):'—'}</b><small>лучшая · ${unit()}</small></div><div><b>${score}%</b><small>освоение</small></div></div><div class="help-copy"><p>${open?`Образцов: ${key?.samples||0}. Цель: ${speed(settings.speedGoal)} ${unit()}. Образец: от ${speed(settings.speedGoal*.7)} ${unit()}, точность от 95%, все слова исправлены. ${!key||key.samples<5?'Пока собираем данные по этой букве.':'Освоение показывает скорость последней качественной попытки относительно цели.'}`:'Буква пока закрыта. Для каждой доступной буквы нужно пять образцов от 70% цели и скорость от 100% цели в последней качественной попытке. Точность — от 95%, все слова исправлены.'}</p></div>${open?`<button class="primary-button" data-focus-letter="${esc(letter)}">Тренировать эту букву</button>`:''}`)}
function customTest(){settingsInDialog=false;openDialog(settings.testMode==='time'?'Продолжительность теста':'Количество слов',`<label class="custom-label" for="customValue">${settings.testMode==='time'?'Секунды или запись с h, m, s — например 1m 30s':'Целое число от 1 до 10000'}</label><input class="custom-input" id="customValue" value="${settings.testMode==='time'?settings.testTime:settings.testWords}" autocomplete="off"><p class="validation-error" id="customError" role="alert"></p><div class="dialog-footer"><span></span><button class="primary-button" data-action="save-custom">Применить</button></div>`)}
function saveCustom(){let raw=$('customValue').value.trim(),value;if(settings.testMode==='time'){if(/^\d+$/.test(raw))value=Number(raw);else if(/^(?:\d+\s*[hms]\s*)+$/i.test(raw)){value=0;for(let m of raw.matchAll(/(\d+)\s*([hms])/gi))value+=Number(m[1])*({h:3600,m:60,s:1})[m[2].toLowerCase()]}if(!Number.isInteger(value)||value<1||value>14400){$('customError').textContent='Укажи время от 1 секунды до 4 часов.';return}settings.testTime=value}else{value=Number(raw);if(!Number.isInteger(value)||value<1||value>10000){$('customError').textContent='Укажи целое число от 1 до 10000.';return}settings.testWords=value}persist();$('dialog').close();render()}
function repeat(){if(!session)return;let words=[...session.words],ctx={...context};if(ctx.activity==='code'){makeSession(words,ctx);$('content').innerHTML=codeControls()+exerciseMarkup();bindSession();$('typingInput').focus({preventScroll:true});return;}if(ctx.kind==='activity'){if(ctx.activity==='control')ctx.activity='review';startActivity(words,ctx);$('typingInput').focus({preventScroll:true});return;}makeSession(words,ctx);if(view==='practice')$('content').innerHTML=panelMarkup()+exerciseMarkup();else if(view==='test')$('content').innerHTML=testControls()+exerciseMarkup();else $('content').innerHTML=`<div class="session-meta"><button class="soft-button" data-view="lessons">← Список уроков</button><strong>${ctx.group+1}.${ctx.step+1} · ${STEP_NAMES[ctx.step]}</strong><span>цель ${lessonThreshold(context).cpm||'спокойный темп'}${lessonThreshold(context).cpm?' CPM':''} · 95%</span></div>`+exerciseMarkup();bindSession();$('typingInput').focus({preventScroll:true})}
function nextLesson(){let g=context.group,st=context.step+1;if(st>=LESSON_GROUPS[g][1]){g++;st=0}if(g>=LESSON_GROUPS.length){toast('Ты прошёл весь курс. Продолжай адаптивную практику!');navigate('lessons');return}context={group:g,step:st};view='lesson';render();$('typingInput').focus({preventScroll:true})}
function mistakes(){if(!session?.result?.misspelled.length)return;let words=[...session.result.misspelled];if(context.kind!=='test'){startActivity(words,{activity:'mistakes',title:'Короткая работа над ошибками',reason:'Слова из последней попытки. Каждая ошибка добавляет повтор; после коррекции вернись к новому контексту.'});$('typingInput').focus({preventScroll:true});return;}makeSession(words,{kind:'test',mode:'words',testMode:'mistakes',wordLimit:words.length});$('content').innerHTML=`<div class="session-meta"><strong>Работа над ошибками · ${words.length} ${words.length%10===1&&words.length%100!==11?'слово':words.length%10>=2&&words.length%10<=4&&(words.length%100<12||words.length%100>14)?'слова':'слов'}</strong><button class="soft-button" data-view="test">← Обычный тест</button></div>`+exerciseMarkup();bindSession();$('typingInput').focus({preventScroll:true})}
function downloadResult(){if(!session?.result)return;let r=session.result,c=document.createElement('canvas');c.width=1200;c.height=680;let g=c.getContext('2d');g.fillStyle=settings.theme==='dark'?'#101317':settings.theme==='light'?'#f6f8fa':'#f3efe7';g.fillRect(0,0,c.width,c.height);g.fillStyle=settings.theme==='dark'?'#70e4b4':'#087956';g.font='bold 35px monospace';g.fillText('Десять пальцев',70,90);g.fillStyle=settings.theme==='dark'?'#dce5ee':'#223246';g.font='22px monospace';g.fillText(language().name+' · '+date(Date.now()),70,145);[[speed(r.cpm),unit()],[(Math.round(r.accuracy)+'%'),'точность'],[formatDuration(r.duration),'время']].forEach(([v,n],i)=>{g.font='68px monospace';g.fillText(v,70+i*370,310);g.font='22px monospace';g.fillText(n,70+i*370,355)});g.font='20px monospace';g.fillText(`Правильных символов: ${r.correct}   Ошибочных позиций: ${r.errors}`,70,460);g.fillText('Регулярная практика. Уверенный навык.',70,570);c.toBlob(blob=>{let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='typing-result.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})}
$('sidebar').addEventListener('click',handleClick);$('header').addEventListener('click',handleClick);$('content').addEventListener('pointerdown',e=>{if(e.target.closest('button[data-action="pause"]'))e.preventDefault()});$('content').addEventListener('click',handleClick);$('dialog').addEventListener('click',handleClick);$('content').addEventListener('change',e=>{if(e.target.dataset.setting)changeSetting(e.target);else coach.handleChange(e.target)});$('content').addEventListener('input',e=>coach.rememberDraft(e.target));$('dialog').addEventListener('change',e=>{if(e.target.dataset.setting)changeSetting(e.target);else coach.handleChange(e.target)});$('dialog').addEventListener('cancel',e=>{e.preventDefault();closeDialog()});$('dialog').addEventListener('click',e=>{if(e.target===$('dialog')){let r=$('dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});
function handleClick(e){let b=e.target.closest('button');if(!b||b.disabled)return;if(onboarding.handleClick(b))return;if(b.dataset.trainingLanguage){selectTrainingLanguage(b.dataset.trainingLanguage);return}if(b.dataset.startLanguage){selectTrainingLanguage(b.dataset.startLanguage,true);return}if(b.dataset.codeTrack&&CODE_TRACKS[b.dataset.codeTrack]){codeTrack=b.dataset.codeTrack;codeRound=-1;render();return}if(coach.handleClick(b))return;if(b.dataset.view){navigate(b.dataset.view);return}if(b.dataset.group!==undefined){context={group:Number(b.dataset.group),step:Number(b.dataset.step)};view='lesson';location.hash='lessons';render();return}if(b.dataset.letter){letterDialog(b.dataset.letter);return}if(b.dataset.focusLetter){forcedFocus=b.dataset.focusLetter;$('dialog').close();view='practice';location.hash='practice';render();$('typingInput').focus({preventScroll:true});return}if(b.dataset.testMode){settings.testMode=b.dataset.testMode;persist();render();return}if(b.dataset.testAmount){settings[settings.testMode==='time'?'testTime':'testWords']=Number(b.dataset.testAmount);persist();render();return}if(b.dataset.settingsTab){settingsTab=b.dataset.settingsTab;if(settingsInDialog)$('dialog').innerHTML=`<div class="dialog-header"><h2>Настройки</h2><button data-action="close-dialog" aria-label="Закрыть">${icon('close')}</button></div>`+settingsMarkup();else $('content').innerHTML=settingsMarkup();return}if(b.dataset.theme){settings.theme=b.dataset.theme;persist();applySettings();themes();return}if(b.dataset.guide){if(b.dataset.guide==='back')guideStep=Math.max(0,guideStep-1);else if(guideStep<guide.length-1)guideStep++;else{data.guideSeen=true;persist();closeDialog();$('typingInput')?.focus({preventScroll:true});return}showGuide();return}
 switch(b.dataset.action){case'retry-save':retrySave();break;case'hint':requestHint();break;case'close-dialog':closeDialog();break;case'practice-settings':case'language':openSettings('practice');break;case'help':help();break;case'guide':guideStep=0;showGuide();break;case'themes':themes();break;case'punctuation':settings.punctuation=!settings.punctuation;persist();render();break;case'custom-test':customTest();break;case'save-custom':saveCustom();break;case'repeat':repeat();break;case'regenerate':if(view==='activity'){coach.startPhase(context.phase||'target');break;}forcedFocus=null;render();$('typingInput')?.focus({preventScroll:true});break;case'pause':if(session?.status==='paused'){$('typingInput').focus({preventScroll:true})}else if(session){session.pause();$('typingInput')?.blur();paint()}break;case'next-lesson':nextLesson();break;case'mistakes':mistakes();break;case'result-image':downloadResult();break;}
}
